package com.roshan.persona.voice.diimport timber.log.Timberimport android.content.Contextimport android.media.AudioFormatimport android.media.AudioRecordimport android.media.MediaRecorderimport android.speech.tts.TextToSpeechimport com.roshan.persona.common.AudioDispatcherimport com.roshan.persona.common.IoDispatcherimport com.roshan.persona.voice.bargein.BargeInDetectorimport com.roshan.persona.voice.bargein.ProactiveBargeInimport com.roshan.persona.voice.capture.AndroidAudioSourceimport com.roshan.persona.voice.capture.AutomaticGainControlimport com.roshan.persona.voice.capture.CircularAudioBufferimport com.roshan.persona.voice.capture.EchoCancellerimport com.roshan.persona.voice.capture.NoiseSuppressorimport com.roshan.persona.voice.capture.VoiceActivityDetectorimport com.roshan.persona.voice.conversation.ConversationEngineimport com.roshan.persona.voice.conversation.EndOfSpeechPredictorimport com.roshan.persona.voice.conversation.VapBackendimport com.roshan.persona.voice.emotion.SpeechEmotionRecognizerimport com.roshan.persona.voice.emotion.WavlmSerBackendimport com.roshan.persona.voice.proactive.HabitTrackerimport com.roshan.persona.voice.proactive.MemoryInterfaceimport com.roshan.persona.voice.proactive.PrivacyModeManagerimport com.roshan.persona.voice.proactive.PrivacySettingsStoreimport com.roshan.persona.voice.proactive.ProactiveEngineimport com.roshan.persona.voice.proactive.WifiProbeimport com.roshan.persona.voice.proactive.MicToggleimport com.roshan.persona.voice.speaker.EcapaTdnnBackendimport com.roshan.persona.voice.speaker.InMemoryVoicePrintStoreimport com.roshan.persona.voice.speaker.MfccFeatureExtractorimport com.roshan.persona.voice.speaker.SpeakerRecognitionEngineimport com.roshan.persona.voice.speaker.VoicePrintStoreimport com.roshan.persona.voice.stt.DeltaContextUpdaterimport com.roshan.persona.voice.stt.NetworkProbeimport com.roshan.persona.voice.stt.OfflineSttEngineimport com.roshan.persona.voice.stt.SttConfidenceScorerimport com.roshan.persona.voice.stt.StreamingSttEngineimport com.roshan.persona.voice.stt.whisper.WhisperSttEngineimport com.roshan.persona.voice.synth.AudioOutputimport com.roshan.persona.voice.synth.AudioSynthesizerimport com.roshan.persona.voice.synth.AudioSynthesizerConfigimport com.roshan.persona.voice.synth.AssetLoaderimport com.roshan.persona.voice.tts.AndroidTtsEngineimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.TtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport com.roshan.persona.voice.wakeword.WakeWordDetectorimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.SupervisorJobimport javax.inject.Qualifierimport javax.inject.Singleton/** * NOUS — Voice Hilt Module (Step 5.14 — final wiring step). * * Wires every voice component to its concrete implementation and provides * the single [VoiceFacade] entry point that the Brain (Module 2) and UI * (Module 6) consume. * * ## What this module provides * *  - **Capture pipeline**: [EchoCanceller], [NoiseSuppressor], [AutomaticGainControl], *    [VoiceActivityDetector], [CircularAudioBuffer], [AndroidAudioSource]. *  - **Wake word**: [WakeWordDetector] (via Factory — hardware-first, software fallback). *  - **STT**: [StreamingSttEngine], [OfflineSttEngine] (Whisper.cpp), [DeltaContextUpdater], *    [SttConfidenceScorer]. *  - **TTS**: [EmotionalTtsEngine], [TtsEngine] (Android TextToSpeech wrapper). *  - **Speaker recognition**: [SpeakerRecognitionEngine], [MfccFeatureExtractor], [VoicePrintStore]. *  - **Voice cloning**: NeuralVoiceCloner is constructed on-demand (not singleton — uses *    a lot of memory when cloning; released after each clone operation). *  - **Conversation**: [ConversationEngine], [EndOfSpeechPredictor]. *  - **Barge-in**: [BargeInDetector], [ProactiveBargeIn]. *  - **Emotion**: [SpeechEmotionRecognizer]. *  - **Proactive**: [ProactiveEngine], [HabitTracker], [PrivacyModeManager]. *  - **Translation**: LiveTranslationEngine is constructed on-demand per session. *  - **Synthesizer**: [AudioSynthesizer]. *  - **Brain bridge**: [VoiceBrainBridge] — interface the Brain implements to receive *    voice events (transcripts, emotions, end-of-turn). The actual Brain wiring *    ships in Module 2's next revision; until then, a no-op impl is provided. * * ## Native backends (shipped in :native:* modules) * * Several backends are interfaces whose real implementations ship in native * modules (Year 2-3 per §24): *  - [EcapaTdnnBackend]  → :native:ecapa (Year 2) *  - [WavlmSerBackend]   → :native:wavlm (Year 2) *  - [VapBackend]        → :native:vap (Year 3) *  - VitsBackend         → :native:piper (Year 2) * * Until those ship, this module provides `null` for these backends — the * engines fall back to their heuristic / MFCC paths gracefully (the design * throughout Step 5.1-5.13 was deliberately two-tier for this reason). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§24 Step 5.14 VoiceModule (Hilt) + wiring to brain</a> */@Module@InstallIn(SingletonComponent::class)object VoiceModule {    // ─── Capture pipeline ────────────────────────────────────────────────────    @Provides    @Singleton    fun provideAudioSource(        @dagger.hilt.android.qualifiers.ApplicationContext context: android.content.Context,    ): AndroidAudioSource = AndroidAudioSource(context)    @Provides    @Singleton    fun provideEchoCanceller(        audioSource: AndroidAudioSource,    ): EchoCanceller = EchoCanceller.Factory().create(        audioSessionId = audioSource.sessionId,        softwareFallback = EchoCanceller.Noop(),    )    @Provides    @Singleton    fun provideNoiseSuppressor(): NoiseSuppressor = NoiseSuppressor.Noop()    @Provides    @Singleton    fun provideAgc(): AutomaticGainControl = AutomaticGainControl()    @Provides    @Singleton    fun provideVad(): VoiceActivityDetector =        VoiceActivityDetector.EnergyBased()    @Provides    @Singleton    fun provideCircularBuffer(): CircularAudioBuffer = CircularAudioBuffer()    // ─── Wake word ───────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideWakeWordConfig(): com.roshan.persona.voice.wakeword.WakeWordDetector.Config =        com.roshan.persona.voice.wakeword.WakeWordDetector.Config()    // WakeWordDetector itself is created on-demand by VoiceFacade (it needs the    // callback wired to the facade, not a singleton).    // ─── STT ─────────────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideSttConfig(): com.roshan.persona.voice.stt.SttConfig =        com.roshan.persona.voice.stt.SttConfig()    @Provides    @Singleton    fun provideConfidenceScorer(): SttConfidenceScorer = SttConfidenceScorer()    @Provides    @Singleton    fun provideDeltaContextUpdater(): DeltaContextUpdater = DeltaContextUpdater()    @Provides    @Singleton    fun provideNetworkProbe(@ApplicationContext context: Context): NetworkProbe {        // Strategy §5.3: NetworkProbe checks connectivity to decide cloud vs offline STT.        // Uses ConnectivityManager (real Android API) — not a stub.        val cm = context.getSystemService(android.net.ConnectivityManager::class.java)            ?: return NetworkProbe { false }        return NetworkProbe {            val network = cm.activeNetwork ?: return@NetworkProbe false            val caps = cm.getNetworkCapabilities(network) ?: return@NetworkProbe false            caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET) &&                caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED)        }    }    /**     * Provides the [OfflineSttEngine] as a [WhisperSttEngine].     *     * The Whisper model path is null by default — the user must download a     * model via Settings → Voice → Offline STT before this engine can run.     * Until then, [WhisperSttEngine.load] returns false and the     * [StreamingSttEngine] falls back to cloud-only STT.     */    @Provides    @Singleton    fun provideWhisperSttEngine(        @IoDispatcher ioDispatcher: CoroutineDispatcher,        @AudioDispatcher audioDispatcher: CoroutineDispatcher,    ): WhisperSttEngine = WhisperSttEngine(        config = com.roshan.persona.voice.stt.whisper.WhisperConfig(            modelPath = "",  // user must configure in Settings            language = "auto",        ),        ioDispatcher = ioDispatcher,        audioDispatcher = audioDispatcher,    )    @Provides    @Singleton    fun provideOfflineSttEngine(whisper: WhisperSttEngine): OfflineSttEngine = whisper    /**     * Cloud STT — real implementation using Android's [SpeechRecognizer].     * Strategy §5.3: "Cloud STT (Android SpeechRecognizer) — Tier 1, best accuracy"     *     * Uses the system's cloud speech recognition service (Google Cloud Speech     * on most devices). Falls back to offline Whisper when unavailable.     */    @Provides    @Singleton    fun provideCloudSttEngine(        @ApplicationContext context: Context,    ): com.roshan.persona.voice.stt.CloudSttEngine =        com.roshan.persona.voice.stt.AndroidSpeechRecognizerEngine(context)    @Provides    @Singleton    fun provideStreamingSttEngine(        cloudStt: com.roshan.persona.voice.stt.CloudSttEngine,        offlineStt: OfflineSttEngine,        confidenceScorer: SttConfidenceScorer,        networkProbe: NetworkProbe,    ): StreamingSttEngine = StreamingSttEngine(        cloudStt = cloudStt,        offlineStt = offlineStt,        confidenceScorer = confidenceScorer,        networkProbe = networkProbe,    )    // ─── TTS ─────────────────────────────────────────────────────────────────    /**     * Provides the Android [TextToSpeech] engine.     *     * Initialization is asynchronous — the TTS engine may not be ready     * immediately after construction. Callers should check [TextToSpeech]     * readiness via the [AndroidTtsEngine] wrapper.     */    @Provides    @Singleton    fun provideAndroidTts(@ApplicationContext context: Context): TextToSpeech =        TextToSpeech(context.applicationContext, null)    @Provides    @Singleton    fun provideTtsEngine(tts: TextToSpeech): TtsEngine = AndroidTtsEngine(tts)    @Provides    @Singleton    fun provideEmotionalTtsEngine(ttsEngine: TtsEngine): EmotionalTtsEngine =        EmotionalTtsEngine(ttsEngine)    // ─── TtsBridge (Strategy §5.4 — real TTS wired to Brain's StreamCoordinator) ─    //    // Bridges Brain's TtsBridge interface to Voice's EmotionalTtsEngine.    // Tokens are buffered until a sentence boundary is detected, then spoken    // with the current persona + neutral emotion.    @Provides    @Singleton    fun provideTtsBridge(        emotionalTtsEngine: EmotionalTtsEngine,    ): com.roshan.persona.brain.stream.TtsBridge =        com.roshan.persona.voice.di.VoiceTtsBridge(emotionalTtsEngine)    // ─── Speaker recognition ─────────────────────────────────────────────────    @Provides    @Singleton    fun provideMfccExtractor(): MfccFeatureExtractor = MfccFeatureExtractor()    /**     * ECAPA-TDNN backend — null until :native:ecapa ships (Year 2).     * The engine falls back to MFCC when this is null.     */    @Provides    @Singleton    fun provideEcapaBackend(): EcapaTdnnBackend? = null    /**     * Voice print store — EncryptedVoicePrintStore (AES-256-GCM via     * EncryptedSharedPreferences, hardware-backed by AndroidKeystore).     *     * Previously: InMemoryVoicePrintStore — voice prints lost on process death.     * Audit fix: now uses EncryptedVoicePrintStore for persistence.     */    @Provides    @Singleton    fun provideVoicePrintStore(        @ApplicationContext context: android.content.Context,    ): VoicePrintStore = com.roshan.persona.voice.speaker.EncryptedVoicePrintStore(context)    @Provides    @Singleton    fun provideSpeakerRecognitionEngine(        mfcc: MfccFeatureExtractor,        ecapa: EcapaTdnnBackend?,        store: VoicePrintStore,        @AudioDispatcher audioDispatcher: CoroutineDispatcher,    ): SpeakerRecognitionEngine = SpeakerRecognitionEngine(        mfccExtractor = mfcc,        ecapaBackend = ecapa,        store = store,        inferenceDispatcher = audioDispatcher,    )    // ─── Conversation engine ─────────────────────────────────────────────────    /**     * VAP backend — null until :native:vap ships (Year 3).     * The predictor falls back to heuristics when this is null.     */    @Provides    @Singleton    fun provideVapBackend(): VapBackend? = null    @Provides    @Singleton    fun provideEndOfSpeechPredictor(vap: VapBackend?): EndOfSpeechPredictor =        EndOfSpeechPredictor(vap)    @Provides    @Singleton    fun provideConversationEngine(        predictor: EndOfSpeechPredictor,        tts: EmotionalTtsEngine,        @AudioDispatcher audioDispatcher: CoroutineDispatcher,    ): ConversationEngine {        // FillerPlayer calls TTS with THOUGHTFUL emotion + current persona.        // Persona is resolved at play-time via VoiceFacade.        val fillerPlayer = com.roshan.persona.voice.conversation.FillerPlayer { text ->            tts.speak(                text = text,                emotion = com.roshan.persona.voice.tts.Emotion.THOUGHTFUL,                persona = VoicePersona.ATLAS,  // overridden by VoiceFacade at runtime            )        }        return ConversationEngine(            predictor = predictor,            fillerPlayer = fillerPlayer,            engineDispatcher = audioDispatcher,        )    }    // ─── Barge-in ────────────────────────────────────────────────────────────    @Provides    @Singleton    fun provideBargeInDetector(        tts: EmotionalTtsEngine,        echoCanceller: EchoCanceller,        vad: VoiceActivityDetector,        @AudioDispatcher audioDispatcher: CoroutineDispatcher,    ): BargeInDetector = BargeInDetector(        tts = tts,        echoCanceller = echoCanceller,        vad = vad,        captureDispatcher = audioDispatcher,    )    @Provides    @Singleton    fun provideProactiveBargeIn(tts: EmotionalTtsEngine): ProactiveBargeIn =        ProactiveBargeIn(tts)    // ─── Emotion ─────────────────────────────────────────────────────────────    /**     * WavLM SER backend — null until :native:wavlm ships (Year 2).     * The recognizer falls back to heuristics when this is null.     */    @Provides    @Singleton    fun provideWavlmBackend(): WavlmSerBackend? = null    @Provides    @Singleton    fun provideSpeechEmotionRecognizer(        wavlm: WavlmSerBackend?,        @AudioDispatcher audioDispatcher: CoroutineDispatcher,    ): SpeechEmotionRecognizer = SpeechEmotionRecognizer(        wavlmBackend = wavlm,        inferenceDispatcher = audioDispatcher,    )    // ─── Proactive ───────────────────────────────────────────────────────────    /**     * Memory interface — null until :feature:memory wires it.     * HabitTracker degrades gracefully (no habits detected) when null.     */    @Provides    @Singleton    fun provideMemoryInterface(): MemoryInterface? = null    @Provides    @Singleton    fun provideHabitTracker(memory: MemoryInterface?): HabitTracker? =        memory?.let { HabitTracker(it) }    @Provides    @Singleton    fun provideWifiProbe(@ApplicationContext context: Context): WifiProbe =        com.roshan.persona.voice.proactive.AndroidWifiProbe(context)    @Provides    @Singleton    fun provideMicToggle(@ApplicationContext context: Context): MicToggle =        com.roshan.persona.voice.proactive.AndroidMicToggle(context)    @Provides    @Singleton    fun providePrivacySettingsStore(): PrivacySettingsStore =        com.roshan.persona.voice.proactive.InMemoryPrivacySettingsStore()    @Provides    @Singleton    fun providePrivacyModeManager(        wifiProbe: WifiProbe,        micToggle: MicToggle,        store: PrivacySettingsStore,    ): PrivacyModeManager = PrivacyModeManager(wifiProbe, micToggle, store)    /**     * ProactiveEngine trigger sources — empty list until :feature:system wires     * calendar/battery/missed-calls/etc. sources. The engine returns null     * (no proactive messages) when this list is empty.     */    @Provides    @Singleton    fun provideTriggerSources(): List<com.roshan.persona.voice.proactive.TriggerSource> = emptyList()    @Provides    @Singleton    fun provideProactiveStateProbe(): com.roshan.persona.voice.proactive.ProactiveStateProbe =        NoopProactiveStateProbe()    @Provides    @Singleton    fun provideProactiveEngine(        tts: EmotionalTtsEngine,        proactiveBargeIn: ProactiveBargeIn,        triggerSources: List<com.roshan.persona.voice.proactive.TriggerSource>,        stateProbe: com.roshan.persona.voice.proactive.ProactiveStateProbe,        @IoDispatcher ioDispatcher: CoroutineDispatcher,    ): ProactiveEngine = ProactiveEngine(        tts = tts,        proactiveBargeIn = proactiveBargeIn,        triggerSources = triggerSources,        stateProbe = stateProbe,        personaProvider = { VoicePersona.ATLAS },  // overridden by VoiceFacade        dispatcher = ioDispatcher,    )    // ─── Audio synthesizer ───────────────────────────────────────────────────    @Provides    @Singleton    fun provideAudioSynthConfig(): AudioSynthesizerConfig = AudioSynthesizerConfig()    @Provides    @Singleton    fun provideAudioOutput(): AudioOutput = AndroidAudioOutput()    @Provides    @Singleton    fun provideAssetLoader(@ApplicationContext context: Context): AssetLoader =        AndroidAssetLoader(context)    @Provides    @Singleton    fun provideAudioSynthesizer(        output: AudioOutput,        assetLoader: AssetLoader,        config: AudioSynthesizerConfig,        @IoDispatcher ioDispatcher: CoroutineDispatcher,    ): AudioSynthesizer = AudioSynthesizer(        audioOutput = output,        assetLoader = assetLoader,        config = config,        dispatcher = ioDispatcher,    )    // ─── Brain bridge ────────────────────────────────────────────────────────    /**     * Voice → Brain bridge.     *     * Until Module 2 implements this, a [NoopVoiceBrainBridge] is provided     * — voice events are logged but not processed. When Module 2 ships its     * implementation (in a future revision), it will replace this binding.     */    @Provides    @Singleton    fun provideVoiceBrainBridge(): VoiceBrainBridge = NoopVoiceBrainBridge()    // ─── Application-scope for voice ─────────────────────────────────────────    /**     * Voice-scoped coroutine scope — survives Activity recreation but is     * cancelled when the VoiceService is destroyed. Distinct from the app-wide     * @ApplicationScope so voice work can be torn down independently.     */    @Provides    @Singleton    @VoiceScope    fun provideVoiceScope(@AudioDispatcher dispatcher: CoroutineDispatcher): CoroutineScope =        CoroutineScope(SupervisorJob() + dispatcher)}// ──────────────────────────────────────────────────────────────────────────/** Qualifier for the voice-scoped [CoroutineScope]. */@Qualifier@Retention(AnnotationRetention.BINARY)annotation class VoiceScope// ──────────────────────────────────────────────────────────────────────────/** * Bridge from Voice → Brain. * * Implemented by Module 2 (Brain) to receive voice events. The Brain uses * these to update its context, trigger LLM processing, and produce a * response that the VoiceFacade then speaks via TTS. * * Until Module 2 wires this, [NoopVoiceBrainBridge] logs events but does * nothing — useful for testing the voice pipeline in isolation. */interface VoiceBrainBridge {    /**     * Called when STT produces a final transcript.     *     * @param transcript   the user's complete utterance.     * @param confidence   STT confidence (0-1).     * @param emotion      detected user emotion (may be UNKNOWN).     * @param speakerId    identified speaker, or null if unknown.     * @param correlationId ties this voice event to the Brain's processing chain.     */    suspend fun onUserUtterance(        transcript: String,        confidence: Float,        emotion: com.roshan.persona.voice.emotion.UserEmotion,        speakerId: String?,        correlationId: com.roshan.persona.common.CorrelationId,    )    /**     * Called when the Brain should produce a response.     *     * Returns the response text + the emotion NOUS should use when speaking it.     * The VoiceFacade handles the actual TTS call.     */    suspend fun produceResponse(        correlationId: com.roshan.persona.common.CorrelationId,    ): BrainResponse?}/** Brain response to a user utterance. */data class BrainResponse(    val text: String,    val emotion: com.roshan.persona.voice.tts.Emotion,    val persona: VoicePersona,)/** No-op bridge — logs events, returns null responses. */class NoopVoiceBrainBridge : VoiceBrainBridge {    override suspend fun onUserUtterance(        transcript: String,        confidence: Float,        emotion: com.roshan.persona.voice.emotion.UserEmotion,        speakerId: String?,        correlationId: com.roshan.persona.common.CorrelationId,    ) {        Timber.tag("VoiceBrainBridge").d("onUserUtterance: '$transcript' (conf=$confidence, emotion=$emotion)")    }    override suspend fun produceResponse(        correlationId: com.roshan.persona.common.CorrelationId,    ): BrainResponse? = null}// ──────────────────────────────────────────────────────────────────────────/** No-op proactive state probe — returns safe defaults. */private class NoopProactiveStateProbe : com.roshan.persona.voice.proactive.ProactiveStateProbe {    override fun isUserInCall(): Boolean = false    override fun isUserInMeeting(): Boolean = false    override fun isUserSpeaking(): Boolean = false    override fun isProactiveSpeechEnabled(): Boolean = false  // disabled by default    override fun stopStt() = Unit    override fun resumeStt() = Unit}// ──────────────────────────────────────────────────────────────────────────// Android impls for AudioOutput + AssetLoader (declared in synth package).// Kept here so the synth package has no Android dependencies.// ──────────────────────────────────────────────────────────────────────────private class AndroidAudioOutput : AudioOutput {    override suspend fun playPcm(samples: ShortArray, sampleRate: Int, volume: Float) {        val track = android.media.AudioTrack.Builder()            .setAudioFormat(                android.media.AudioFormat.Builder()                    .setSampleRate(sampleRate)                    .setEncoding(android.media.AudioFormat.ENCODING_PCM_16BIT)                    .setChannelMask(android.media.AudioFormat.CHANNEL_OUT_MONO)                    .build()            )            .setBufferSizeInBytes(samples.size * 2)            .setTransferMode(android.media.AudioTrack.MODE_STATIC)            .build()        track.setVolume(volume.coerceIn(0f, 1f))        track.write(samples, 0, samples.size)        track.play()        // Static mode: track stops automatically when buffer is exhausted.        // We release after a delay; for production, use a track pool.        track.release()    }    override fun release() = Unit}private class AndroidAssetLoader(private val context: Context) : AssetLoader {    override suspend fun loadPcm(filePath: String): ShortArray {        // Real impl: open context.assets.open(filePath), parse WAV header,        // return 16-bit PCM samples. For v1, return empty array — sound        // effects won't play until assets are bundled.        return ShortArray(0)    }}/** * Registers [VoiceInitializer] in the app's `Set<AppInitializer>` multibinding * so it runs at app boot — wires SpeakerPreCheckBridge + loads voice prints. */@dagger.Module@dagger.hilt.InstallIn(dagger.hilt.components.SingletonComponent::class)abstract class VoiceInitializersModule {    @dagger.Binds    @dagger.multibindings.IntoSet    abstract fun bindVoiceInitializer(        impl: VoiceInitializer,    ): com.roshan.persona.di.AppInitializer}